import{_ as e,c as s,o as r,a2 as o}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"ResetPasswordController","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"ResetPasswordController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/auth/reset-password-controller.md","filePath":"system-reference/backend/http/controllers/auth/reset-password-controller.md","lastUpdated":1778363927000}'),t={name:"system-reference/backend/http/controllers/auth/reset-password-controller.md"},a=o('<h1 id="resetpasswordcontroller" tabindex="-1">ResetPasswordController <a class="header-anchor" href="#resetpasswordcontroller" aria-label="Permalink to &quot;ResetPasswordController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/Auth/ResetPasswordController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers\\Auth</code><br><strong>Extends</strong>: <code>Auth\\Controller</code><br><strong>Traits</strong>: <code>ResetsPasswords</code>, <code>RespondsWithJsonOrRedirect</code></p><p>Handles the password reset flow after the user clicks the reset link from the <a href="./forgot-password-controller">ForgotPasswordController</a> email. Also supports a &quot;welcome&quot; flow for new users who receive an invitation link.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="broker-passwordbroker" tabindex="-1"><code>broker(): PasswordBroker</code> <a class="header-anchor" href="#broker-passwordbroker" aria-label="Permalink to &quot;`broker(): PasswordBroker`&quot;">​</a></h3><p>Returns the password broker configured for the Modularous auth provider via <code>Modularous::getAuthProviderName()</code>.</p><h3 id="showresetform-request-request-token-null-view-redirectresponse" tabindex="-1"><code>showResetForm(Request $request, $token = null): View|RedirectResponse</code> <a class="header-anchor" href="#showresetform-request-request-token-null-view-redirectresponse" aria-label="Permalink to &quot;`showResetForm(Request $request, $token = null): View|RedirectResponse`&quot;">​</a></h3><p>Displays the password reset form.</p><ol><li>Resolves the user from the token via <code>getUserFromToken()</code>.</li><li>Validates the token against the password reset table.</li><li>Pre-fills the form with the user&#39;s email and the token.</li><li>Renders the reset password view.</li></ol><p>If the token is invalid or expired, redirects to the forgot-password page with an error.</p><h3 id="showwelcomeform-request-request-token-null-view-redirectresponse" tabindex="-1"><code>showWelcomeForm(Request $request, $token = null): View|RedirectResponse</code> <a class="header-anchor" href="#showwelcomeform-request-request-token-null-view-redirectresponse" aria-label="Permalink to &quot;`showWelcomeForm(Request $request, $token = null): View|RedirectResponse`&quot;">​</a></h3><p>Displays the password form for new users who received a welcome/invitation email. Unlike <code>showResetForm</code>, this method does <strong>not</strong> check token expiry — welcome tokens remain valid until used.</p><h3 id="reset-request-request-jsonresponse-redirectresponse" tabindex="-1"><code>reset(Request $request): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#reset-request-request-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`reset(Request $request): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Processes the password reset submission:</p><ol><li>Validates the request (password, confirmation, token, email).</li><li>Calls <code>broker()-&gt;reset()</code> with the credentials and a callback that invokes <code>resetPassword()</code>.</li><li>Returns a success or failure response.</li></ol><h3 id="getuserfromtoken-string-token-user" tabindex="-1"><code>getUserFromToken(string $token): ?User</code> <a class="header-anchor" href="#getuserfromtoken-string-token-user" aria-label="Permalink to &quot;`getUserFromToken(string $token): ?User`&quot;">​</a></h3><p>Resolves a user from a password reset token. Supports both:</p><ul><li><strong>Clear tokens</strong>: direct lookup in the password resets table.</li><li><strong>Hashed tokens</strong> (Laravel 5.4+): iterates all reset records and checks with <code>Hash::check()</code>.</li></ul><p>Returns <code>null</code> if no matching user is found.</p><h3 id="sendresetresponse-request-request-response-jsonresponse-redirectresponse" tabindex="-1"><code>sendResetResponse(Request $request, $response): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#sendresetresponse-request-request-response-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`sendResetResponse(Request $request, $response): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Returns a success response with translated message and redirect to <code>$redirectPath</code>.</p><h3 id="sendresetfailedresponse-request-request-response-jsonresponse-redirectresponse" tabindex="-1"><code>sendResetFailedResponse(Request $request, $response): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#sendresetfailedresponse-request-request-response-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`sendResetFailedResponse(Request $request, $response): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Returns a failure response with the error under the <code>email</code> key.</p><h3 id="success-view" tabindex="-1"><code>success(): View</code> <a class="header-anchor" href="#success-view" aria-label="Permalink to &quot;`success(): View`&quot;">​</a></h3><p>Renders a success page confirming the password was reset, with a button linking to the login form.</p><h2 id="reset-flow" tabindex="-1">Reset Flow <a class="header-anchor" href="#reset-flow" aria-label="Permalink to &quot;Reset Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User clicks reset link in email</span></span>\n<span class="line"><span>  └─ showResetForm() validates token and renders password form</span></span>\n<span class="line"><span>       └─ User submits new password</span></span>\n<span class="line"><span>            └─ reset() validates and updates password</span></span>\n<span class="line"><span>                 ├─ Success → redirect to login</span></span>\n<span class="line"><span>                 └─ Failure → error shown on form</span></span></code></pre></div><h2 id="welcome-flow" tabindex="-1">Welcome Flow <a class="header-anchor" href="#welcome-flow" aria-label="Permalink to &quot;Welcome Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Admin invites new user → welcome email sent with token</span></span>\n<span class="line"><span>  └─ showWelcomeForm() renders password form (no token expiry check)</span></span>\n<span class="line"><span>       └─ User sets password</span></span>\n<span class="line"><span>            └─ reset() saves password and logs user in</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./forgot-password-controller">ForgotPasswordController</a> — sends the reset email that leads to this controller</li><li><a href="./../password-controller">PasswordController</a> — alternative password reset controller with a slightly different flow</li></ul>',31),n=[a];function l(i,d,c,p,h,u){return r(),s("div",null,n)}const k=e(t,[["render",l]]);export{m as __pageData,k as default};
